import { randomBytes, scrypt, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';
const scryptAsync = promisify(scrypt);
const derive = (password, salt) => scryptAsync(password, salt, 64, {
  N: 131072, r: 8, p: 1, maxmem: 256 * 1024 * 1024
});
async function register(password) {
  const salt = randomBytes(16).toString('hex');
  const key = await derive(password, salt);
  return salt + ':' + key.toString('hex');
}
async function verify(password, record) {
  if (!/^[0-9a-f]{32}:[0-9a-f]{128}$/.test(record)) return false;
  const [salt, hex] = record.split(':');
  return timingSafeEqual(await derive(password, salt), Buffer.from(hex, 'hex'));
}
